class Ledger {
    private val mutex = Mutex()

    suspend fun transfer(from: Long, to: Long, cents: Long) = mutex.withLock {
        val a = accounts.load(from)   // suspends with the lock held
        val b = accounts.load(to)
        accounts.save(a.credit(-cents))
        accounts.save(b.credit(cents))
    }
}
